  "onboarding.tutorialImportDesc":
    "Cliquez sur le bouton Importer pour ajouter des documents. Nous prenons en charge les PDF, EPUB, vidéos YouTube, articles web, et plus. Vous pouvez aussi glisser-déposer des fichiers directement sur la page.",
