    "Observez vos connaissances grandir au fil du temps. La page statistiques affiche votre historique de révision, votre série et votre taux de rétention. Des révisions quotidiennes régulières mènent à une meilleure rétention !",
  "onboarding.tutorialQuickTips": "Conseils rapides",
