  "onboarding.tour.chapter.queue": "La file",
  "onboarding.tour.chapter.readExtract": "Lire et extraire",
  "onboarding.tour.chapter.review": "Révision",
  "onboarding.tour.chapter.welcome": "Bienvenue",
  "onboarding.tour.command": "Démarrer la visite guidée",
  "onboarding.tour.done": "Terminé",
  "onboarding.tour.dontShowAgain": "Ne plus afficher",
  "onboarding.tour.import.button.body": "Les PDF, EPUB, articles web, vidéos YouTube et podcasts arrivent tous ici. Cliquez sur Importer pour ouvrir un fichier, ou utilisez l'import d'URL de la barre d'outils pour tout ce qui a un lien.",
  "onboarding.tour.import.button.title": "Importez vos documents",
  "onboarding.tour.import.grid.body": "Les documents importés apparaissent ici. Ouvrez-en un pour commencer à lire et créer des extraits.",
  "onboarding.tour.import.grid.title": "Votre bibliothèque",
  "onboarding.tour.import.url.body": "L'action Importer une URL de la barre d'outils récupère les articles web, les articles arXiv et les transcriptions YouTube. La palette de commandes (Ctrl+K / Cmd+K) fait la même chose sans quitter le clavier.",
  "onboarding.tour.import.url.title": "Importer depuis une URL",
  "onboarding.tour.knowledge.analytics.body": "Consultez votre taux de rétention, votre activité de révision et vos progrès dans le temps. Les chiffres se mettent à jour au fil de vos révisions.",
  "onboarding.tour.knowledge.analytics.title": "Statistiques",
  "onboarding.tour.knowledge.sphere.body": "Une carte spatiale des relations entre vos documents et extraits. Dézoomez pour voir la forme de ce que vous avez appris.",
  "onboarding.tour.knowledge.sphere.title": "Univers de connaissances",
  "onboarding.tour.make.settings.body": "Les paramètres regroupent les thèmes, les raccourcis clavier, la synchronisation, les intégrations, les fournisseurs d'IA et l'algorithme d'apprentissage. Tout ce qui personnalise l'application se trouve ici.",
  "onboarding.tour.make.settings.title": "Personnalisez-la",
  "onboarding.tour.make.workspace.body": "Les espaces de travail partitionnent votre bibliothèque en contextes distincts : recherche, perso, un projet annexe. Basculez entre eux depuis la barre d'outils.",
  "onboarding.tour.make.workspace.title": "Espaces de travail",
  "onboarding.tour.next": "Suivant",
  "onboarding.tour.queue.controls.body": "Lancez une session de révision optimale, basculez la file entre les modes lecture, planning et révision, ou parcourez manuellement. La file est le point central qui pilote votre boucle quotidienne.",
  "onboarding.tour.queue.controls.title": "Contrôles de la file",
  "onboarding.tour.queue.nav.body": "La file contient tout ce que vous avez ajouté : des documents à lire, des extraits à apprendre. Ouvrez-la depuis la navigation pour voir ce qui est dû ensuite ou piocher au hasard.",
  "onboarding.tour.queue.nav.title": "La file",
  "onboarding.tour.read.extract.body": "Sélectionnez un passage dans le lecteur pour l'extraire sous forme d'extrait : une note, une carte mémoire ou un texte à trous. Les extraits deviennent les unités que le planificateur de révisions apprend.",
  "onboarding.tour.read.extract.title": "Créer des extraits",
  "onboarding.tour.read.extracts.body": "Chaque extrait que vous créez est rassemblé ici, rattaché à sa source afin que vous puissiez toujours revenir au contexte d'origine.",
  "onboarding.tour.read.extracts.title": "Le panneau des extraits",
  "onboarding.tour.read.reader.body": "Chaque document s'ouvre dans son propre onglet avec un lecteur conçu pour la lecture longue. La même surface accueille les outils d'extraction que vous découvrirez ensuite.",
  "onboarding.tour.read.reader.title": "Lire dans le lecteur",
  "onboarding.tour.replayTour": "Rejouer la visite guidée",
  "onboarding.tour.resetOnboarding": "Réinitialiser l'accueil",
  "onboarding.tour.resetOnboardingDesc": "Efface le compteur de lancements, le marqueur de fin et la position reprise. La visite s'ouvrira automatiquement au prochain lancement, comme après une installation toute fraîche.",
  "onboarding.tour.review.algorithm.body": "Incrementum embarque plusieurs planificateurs : FSRS-6, SM-18, SM-20 et SM-2. Choisissez celui qui correspond à votre style dans Paramètres → Apprentissage.",
  "onboarding.tour.review.algorithm.title": "Choisissez votre algorithme",
  "onboarding.tour.review.grading.body": "Après chaque carte, choisissez la note correspondant à votre mémorisation. Le planificateur utilise ce signal pour décider quand réafficher la carte : meilleur souvenir, intervalle plus long.",
  "onboarding.tour.review.grading.title": "Contrôles de notation",
  "onboarding.tour.review.nav.body": "Quand les extraits arrivent à échéance, la session de révision vous guide et vous demande dans quelle mesure vous vous en souveniez. Vos réponses entraînent le planificateur de répétition espacée.",
  "onboarding.tour.review.nav.title": "Sessions de révision",
  "onboarding.tour.skip": "Passer la visite",
  "onboarding.tour.stepOf": "Étape {current} sur {total}",
  "onboarding.tour.welcome.body": "Voici une visite rapide de la boucle importer → lire → extraire → réviser. Elle dure environ deux minutes et vous pouvez la quitter à tout moment : Échap ou un clic ailleurs pour mettre en pause, et vous reprendrez où vous en étiez la prochaine fois.",
  "onboarding.tour.welcome.title": "Bienvenue sur Incrementum",
